# Example of unsafe URL construction without input validation
def unsafe_url_constructor(api_url, user_id):
    return f"{api_url}/{user_id}"

# Example of safe URL construction with basic validation and encoding
def safe_url_constructor(api_url, user_id):
    if not user_id:
        return None
    # Basic sanitization by replacing any potential path traversal characters
    sanitized_user_id = user_id.replace('/', '_').replace('..', '_')
    return f"{api_url}/{sanitized_user_id}"
